import itertools
import random
import weakref

def deduped(events, window):
    """The events that survive, as a list. The stream is handed over as a plain iterator, so it can only be read once."""
    return list(dedupe_events(iter(events), window))

def reference(events, window):
    """The rules of the statement, written the slow, obvious way."""
    remembered = {}
    newest = None
    kept = []
    for timestamp, event_id in events:
        newest = timestamp if newest is None else max(newest, timestamp)
        for expired in [key for key, seen_at in remembered.items() if newest - seen_at > window]:
            del remembered[expired]
        if event_id in remembered:
            continue
        kept.append((timestamp, event_id))
        remembered[event_id] = timestamp
    return kept

class Ident:
    """An event id that can be watched: it supports weak references, and two with the same number are the same id."""
    __slots__ = ("n", "__weakref__")

    def __init__(self, n):
        self.n = n

    def __hash__(self):
        return hash(self.n)

    def __eq__(self, other):
        return isinstance(other, Ident) and other.n == self.n

